// The parts of @qwik.dev/core 2.0.0-rc.0's typings CPR's Qwik plugin relies on.
export type JSXOutput = any;
export type FunctionComponent<P = unknown> = {
  renderFn(props: P, key: string | null, flags: number): JSXOutput;
}['renderFn'];
export type PublicProps<PROPS> = PROPS & { key?: string | number | null };
export type Component<PROPS = unknown> = FunctionComponent<PublicProps<PROPS>>;
export type OnRenderFn<PROPS> = (props: PROPS) => JSXOutput;
export declare const component$: <PROPS = unknown>(onMount: OnRenderFn<PROPS>) => Component<PROPS>;
export declare const Slot: FunctionComponent<{ name?: string }>;
export interface Signal<T> {
  value: T;
}
export declare const useSignal: <T>(value: T) => Signal<T>;
